import{_ as a,o as r,c as n,ae as t}from"./chunks/framework.Cqu5Y2mC.js";const u=JSON.parse('{"title":"Gespräch mit Khalig:","description":"","frontmatter":{},"headers":[],"relativePath":"05-Gemeinsam/Khalig.md","filePath":"05-Gemeinsam/Khalig.md"}'),i={name:"05-Gemeinsam/Khalig.md"};function o(s,e,h,d,l,c){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="gesprach-mit-khalig" tabindex="-1">Gespräch mit Khalig: <a class="header-anchor" href="#gesprach-mit-khalig" aria-label="Permalink to &quot;Gespräch mit Khalig:&quot;">​</a></h1><h2 id="gesprach-vom-20-03-2026" tabindex="-1">Gespräch vom 20-03-2026 <a class="header-anchor" href="#gesprach-vom-20-03-2026" aria-label="Permalink to &quot;Gespräch vom 20-03-2026&quot;">​</a></h2><h2 id="wir" tabindex="-1">Wir: <a class="header-anchor" href="#wir" aria-label="Permalink to &quot;Wir:&quot;">​</a></h2><p>Wie verbinden wir uns das erste Mal mit dem Gateway, um die Einstellung zu sehen?</p><h2 id="antwort-khalig" tabindex="-1">Antwort-Khalig: <a class="header-anchor" href="#antwort-khalig" aria-label="Permalink to &quot;Antwort-Khalig:&quot;">​</a></h2><p>Das Gateway benötigt Strom (usb-c) und Ethernet über den Ethernet-Port.<br> Dann taucht es automatisch im Netzwerk aus, sofern es eine DHCP zugewiesen bekommt.<br> Wenn Ihr das Gerät bei euch daheim an die Fritzbox hängen würdet, könntet ihr es einfach unter Netzwerk als Gerät finden.<br> Das Gerät sollte AVA1 heißen (oder ähnlich).<br> Wenn ihr das gerät gefunden habt, einfach auf die IP-Adresse im Browser zugreifen, dann kommt ihr auf einen Webserver auf de Gerät.<br> Es gibt hier keine Login Daten die nötig sind, man kommt direkt auf die Oberfläche und kann mit der Konfiguration starten.</p><h2 id="wir-1" tabindex="-1">Wir: <a class="header-anchor" href="#wir-1" aria-label="Permalink to &quot;Wir:&quot;">​</a></h2><p>Gibt es Standard-Zugangsdaten (Benutzername/ Passwort) für die Weboberfläche?</p><h2 id="antwort-khalig-1" tabindex="-1">Antwort-Khalig: <a class="header-anchor" href="#antwort-khalig-1" aria-label="Permalink to &quot;Antwort-Khalig:&quot;">​</a></h2><p>S.o. keine Logindaten nötig</p><h2 id="wir-2" tabindex="-1">Wir: <a class="header-anchor" href="#wir-2" aria-label="Permalink to &quot;Wir:&quot;">​</a></h2><p>Benötigen wir spezielle Software, um die Daten der Sensoren am Gateway zu empfangen?</p><h2 id="antwort-khalig-2" tabindex="-1">Antwort-Khalig: <a class="header-anchor" href="#antwort-khalig-2" aria-label="Permalink to &quot;Antwort-Khalig:&quot;">​</a></h2><p>Ich verstehe die Frage nicht so richtig.<br> Mit mioty benötigt man- analog zu LoRawan- ein Netzwerk- und Application-Center.<br> Man kann auf der WEPTECH Oberfläche erste sensoren hinzufügen und testen ob das system funktioniert, aber wenn man wie Ihr in ein eigenes Application-Center die Daten senden möchte, benötigt ihr den BSSCI-Schnittstellenmodus und ein Service-Center für den Betrieb.<br> Ich würde euch dafür das Service-Center empfehlen, dass ich gebaut habe. Ihr findet es hier:</p><p><a href="https://github.com/plasmonized/containerized-mioty-Service-Center" target="_blank" rel="noreferrer">plasmonized/containerized-mioty-Service-Center</a>: This is a basic implementation of the mioty BSSCI protocol into an open source servicecenter with GUI. The serviccenter connects automatically to basestations over BSSCI and aggregates the data onto a MQTT Broker you have to provide.</p><p>Ihr müsstet das Servicecenter einfach als Docker Container auf einem Server eurer Wahl installieren und dann das WEPTECH Gateway dort integrieren.<br> Aber ein schritt nach dem anderen- jetzt nehmt erstmal das WEPTECH Gateway in betrieb und versucht mal mit mioty Sensordaten dort zu empfangen, danach können wir gerne das Servicecenter integrieren.</p><hr><h1 id="inbetriebnahme-gateway" tabindex="-1">Inbetriebnahme Gateway <a class="header-anchor" href="#inbetriebnahme-gateway" aria-label="Permalink to &quot;Inbetriebnahme Gateway&quot;">​</a></h1><p>IPad mit WLan verbinden: IoT ,,HGS-WLan-IoT,,</p><ul><li>Passwort: IoTHGSTG133</li></ul><p>IP: 10.85.33.236</p><h2 id="sensor-daten-sensor-neu" tabindex="-1">Sensor Daten Sensor Neu <a class="header-anchor" href="#sensor-daten-sensor-neu" aria-label="Permalink to &quot;Sensor Daten Sensor Neu&quot;">​</a></h2><ul><li>EUI -&gt; Box</li><li>ShAddr: letzte 4 Zahlen von EUI</li><li>PreAtt aktivieren</li><li>Network key folgt</li><li>Applications key folgt</li></ul><h1 id="gesrpach-vom-27-03-2026" tabindex="-1">Gesrpäch vom 27.03.2026 <a class="header-anchor" href="#gesrpach-vom-27-03-2026" aria-label="Permalink to &quot;Gesrpäch vom 27.03.2026&quot;">​</a></h1><p><strong>Wir:</strong><br> Guten Tag Alex, Wir sind noch einmal auf Fragen gestoßen für die wir dich bräuchten. Wir brächten den Application Key und den Network Key . Und was wäre der EUI Typ? MfG,</p><p><strong>Khalig:</strong><br> Zum registrieren der Sensoren bei mioty braucht ihr nur EUI, Network Key und Short Address. Ist etwas anders wie bei lora</p><h3 id="sensoren-erkennbar-an-den-etikett" tabindex="-1">Sensoren erkennbar an den etikett <a class="header-anchor" href="#sensoren-erkennbar-an-den-etikett" aria-label="Permalink to &quot;Sensoren erkennbar an den etikett&quot;">​</a></h3><p><strong>APOQ57189 EUI: FCA84A01000036C8 -&gt; Network Key: 1FBAC79CA83DC2E40F5372EAC20493BB short adrress: 36C8</strong><br><strong>APOQ57198 EUI: FCA84A01000036C9 -&gt; Network Key: B92C28AD997CA3E17893A611BB2A2358 short adrress: 36C9</strong><br><em><strong>Die short address sind immer die letzten 2 Bytes der EUI.</strong></em></p>',28)])])}const b=a(i,[["render",o]]);export{u as __pageData,b as default};
